function rSquared(xs, ys, slope, intercept) {
  const yMean = ys.reduce((a, b) => a + b, 0) / ys.length;
  let ssRes = 0;
  let ssTot = 0;
  for (let i = 0; i < xs.length; i++) {
    ssRes += (ys[i] - (slope * xs[i] + intercept)) ** 2;
    ssTot += (ys[i] - yMean) ** 2;
  }
  return 1 - ssRes / ssTot;
}
